t.script:
                document.addEventListener('DOMContentLoaded', function() {
                    var map = new google.maps.Map(document.getElementById('wwg-map'), {
                        center: {lat: 44.5, lng: -77.5}, zoom: 7,
                        mapTypeControl: false, streetViewControl: false,
                    });
                    var regions = [], hubs = [], lanes = [], services = [], markers = [], polys = [];
                    var selectedOrigin = null, infoDiv = document.getElementById('wwg-info');
                    var priceDiv = document.getElementById('wwg-price');
                    var resetBtn = document.getElementById('wwg-reset');

                    odoo.define('prema_logistics_booking.where_we_go', function(require) {
                        var rpc = require('web.rpc');
                        rpc.query({route: '/logistics/where-we-go/data'}).then(function(data) {
                            regions = data.regions; hubs = data.hubs;
                            lanes = data.lanes; services = data.services;
                            drawAll();
                        });
                    });

                    // Fallback fetch if Odoo module system not loaded yet
                    setTimeout(function() {
                        if (regions.length === 0) {
                            fetch('/logistics/where-we-go/data', {
                                headers: {'Content-Type': 'application/json'},
                                method: 'POST', body: JSON.stringify({})
                            }).then(r => r.json()).then(function(d) {
                                if (d.result) d = d.result;
                                regions = d.regions||[]; hubs = d.hubs||[];
                                lanes = d.lanes||[]; services = d.services||[];
                                drawAll();
                            });
                        }
                    }, 1000);

                    function drawAll() {
                        markers.forEach(function(m) { m.setMap(null); });
                        polys.forEach(function(p) { p.setMap(null); });
                        markers = []; polys = [];
                        regions.forEach(function(r) {
                            var pos = {lat: r.lat||44, lng: r.lng||-78};
                            var marker = new google.maps.Marker({
                                position: pos, map: map,
                                label: String(r.display_number||r.id),
                                title: r.name,
                            });
                            marker.addListener('click', function() { selectOrigin(r, marker); });
                            markers.push(marker);
                        });
                        hubs.forEach(function(h) {
                            var m = new google.maps.Marker({
                                position: {lat: h.lat||43.65, lng: h.lng||-79.66},
                                map: map, icon: {
                                    path: google.maps.SymbolPath.CIRCLE,
                                    scale: 8, fillColor: '#1a73e8', fillOpacity: 0.9,
                                    strokeColor: '#fff', strokeWeight: 2,
                                },
                                title: h.name,
                            });
                            markers.push(m);
                        });
                    }

                    function selectOrigin(region, marker) {
                        selectedOrigin = region;
                        infoDiv.innerHTML = '' + region.name + '
' +
                            (region.main_city||'') + '
' +
                            (region.public_description||'');
                        resetBtn.style.display = 'block';
                        // Highlight valid destinations
                        var destIds = new Set();
                        lanes.forEach(function(l) {
                            if (l.origin_id === region.id) destIds.add(l.dest_id);
                        });
                        markers.forEach(function(m, i) {
                            var r = regions[i];
                            if (r && destIds.has(r.id)) {
                                m.setIcon({
                                    path: google.maps.SymbolPath.CIRCLE,
                                    scale: 6, fillColor: '#0a0', fillOpacity: 0.8,
                                    strokeColor: '#fff', strokeWeight: 1,
                                });
                            }
                        });
                        // Draw routes to destinations
                        hubs.forEach(function(hub) {
                            destIds.forEach(function(did) {
                                var dest = regions.find(function(r) { return r.id === did; });
                                if (dest) {
                                    var line = new google.maps.Polyline({
                                        path: [
                                            {lat: region.lat||44, lng: region.lng||-78},
                                            {lat: hub.lat||43.65, lng: hub.lng||-79.66},
                                            {lat: dest.lat||44, lng: dest.lng||-78},
                                        ],
                                        map: map,
                                        strokeColor: '#1a73e8', strokeOpacity: 0.6, strokeWeight: 2,
                                        icons: [{icon: {path: google.maps.SymbolPath.FORWARD_CLOSED_ARROW}, offset: '100%'}],
                                    });
                                    polys.push(line);
                                }
                            });
                        });
                    }

                    resetBtn.addEventListener('click', function() {
                        selectedOrigin = null;
                        infoDiv.innerHTML = 'Select a pickup region to begin.';
                        priceDiv.innerHTML = '';
                        resetBtn.style.display = 'none';
                        drawAll();
                    });
                });
